<?php
require_once __DIR__ . '/../../../config/presentation.php';
if (!function_exists('can_access')) { http_response_code(403); exit('Acceso no permitido.'); }
$dashboardData = [];
foreach ($datos as $row) {
    $rawStatus = strtolower(trim((string) ($row['nombre_estado'] ?? '')));
    $status = in_array($rawStatus, ['pendiente', 'enviado'], true) ? 'pendiente'
        : ($rawStatus === 'cancelado' ? 'cancelada'
            : ($rawStatus === 'notificado' ? 'notificada' : $rawStatus));
    if (!in_array($status, ['aprobado', 'rechazado', 'pendiente', 'organizando', 'revision_director', 'notificada', 'cancelada'], true)) {
        $status = 'pendiente';
    }

    $areas = [];
    foreach ($areasPorSolicitud[$row['id_solicitud']] ?? [] as $area) {
        $name = trim((string) ($area['area_asignada'] ?? $area['area_original'] ?? ''));
        if ($name !== '') $areas[] = $name;
    }
    if (!$areas && !empty($row['areas'])) {
        $areas = array_values(array_filter(array_map('trim', explode(',', (string) $row['areas']))));
    }
    if (!$areas && ($row['tipo_visita'] ?? 'cengicana') === 'museo_azucar') {
        $areas = ['Museo del Azúcar'];
    }

    $paymentName = strtolower(trim((string) ($row['nombre_estado_pago'] ?? 'pendiente')));
    $dashboardData[] = [
        'id' => (int) $row['id_solicitud'],
        'tipo' => (string) ($row['tipo_visita'] ?? 'cengicana'),
        'areas' => $areas,
        'nombre' => (string) $row['nombre_solicitante'],
        'inst' => (string) $row['nombre_institucion'],
        'tel' => (string) $row['telefono'],
        'correo' => (string) $row['correo'],
        'total' => (float) $row['total_museo'],
        'vis' => (int) $row['cantidad_visitantes'],
        'visitantes' => (string) ($row['visitantes_nombres'] ?? ''),
        'visitantesLista' => array_values($visitantesPorSolicitud[$row['id_solicitud']] ?? []),
        'fecha' => (string) $row['fecha_visita'],
        'hora' => substr((string) $row['hora_visita'], 0, 5),
        'estado' => $status,
        'pago' => (strpos($paymentName, 'pagado') !== false || (int) ($row['id_estado_pago'] ?? 0) === 2) ? 'pagado' : 'pendiente',
        'pagoToken' => (string) ($row['pago_token'] ?? ''),
        'comprobante' => !empty($row['ruta_comprobante_pago']) ? basename((string) $row['ruta_comprobante_pago']) : '',
        'comprobanteNombre' => (string) ($row['nombre_comprobante_pago'] ?? ''),
        'comprobanteFecha' => (string) ($row['fecha_comprobante_pago'] ?? ''),
        'pagoFormularioEnviado' => (int) ($row['correo_formulario_pago_enviado'] ?? 0) === 1,
        'carta' => !empty($row['ruta_carta_pdf']) ? basename((string) $row['ruta_carta_pdf']) : '',
        'correoEnviado' => (int) ($row['correo_enviado'] ?? 0) === 1,
        'puedeRevisar' => $canManageSolicitudes,
        'puedeSala' => $canManageReservaSalones && $canManageSolicitudes,
        'puedePago' => $canManagePayments,
        'puedeCorreo' => $canSendMail && in_array($status, ['aprobado', 'notificada', 'rechazado'], true),
        'puedeOcultar' => $canHideSolicitudes,
        'sala' => empty($row['cengisalas_request_code']) ? null : [
            'codigo' => (string) $row['cengisalas_request_code'],
            'nombre' => (string) $row['cengisalas_space_name'],
            'distribucion' => (string) $row['cengisalas_configuration_name'],
            'horaFin' => substr((string) $row['cengisalas_hora_fin'], 0, 5),
        ],
    ];
}

$internalContacts = [];
foreach ($areasDisponiblesList as $area) {
    $email = trim((string) ($area['correo_area'] ?? ''));
    if ($email === '') continue;
    $internalContacts[] = [
        'id' => (int) ($area['id_area'] ?? 0),
        'name' => trim((string) ($area['profesional_area'] ?? '')) !== ''
            ? (string) $area['profesional_area']
            : 'Contacto de ' . (string) $area['nombre_area'],
        'email' => $email,
        'role' => 'Profesional responsable',
        'area' => (string) $area['nombre_area'],
    ];
}

$requesterContacts = [];
foreach ($datos as $row) {
    $email = strtolower(trim((string) ($row['correo'] ?? '')));
    if ($email === '') continue;
    if (!isset($requesterContacts[$email])) {
        $requesterContacts[$email] = [
            'name' => (string) ($row['nombre_solicitante'] ?? ''),
            'institution' => (string) ($row['nombre_institucion'] ?? ''),
            'email' => (string) ($row['correo'] ?? ''),
            'phone' => (string) ($row['telefono'] ?? ''),
            'requests' => 0,
            'lastRequest' => (string) ($row['fecha_registro'] ?? ''),
        ];
    }
    $requesterContacts[$email]['requests']++;
    if ((string) ($row['fecha_registro'] ?? '') > $requesterContacts[$email]['lastRequest']) {
        $requesterContacts[$email]['lastRequest'] = (string) $row['fecha_registro'];
    }
}
$requesterContacts = array_values($requesterContacts);

$permissionLabels = [
    'ver_dashboard' => 'Ver panel',
    'ver_reportes' => 'Ver reportes',
    'gestionar_roles_visitas' => 'Administrar usuarios y roles',
    'gestionar_solicitudes' => 'Gestionar solicitudes',
    'ver_solicitudes' => 'Ver solicitudes',
    'gestionar_pagos' => 'Gestionar pagos',
    'ver_pagos' => 'Ver pagos',
    'gestionar_areas' => 'Gestionar áreas',
    'gestionar_reserva_salones' => 'Solicitar salones',
    'ver_solicitudes_aprobadas' => 'Ver solicitudes aprobadas',
    'enviar_correos' => 'Enviar correos',
    'ocultar_solicitudes' => 'Ocultar solicitudes',
];
$currentPermissions = [];
foreach ((array) ($_SESSION['user_permissions'] ?? []) as $permission) {
    $currentPermissions[] = [
        'code' => (string) $permission,
        'name' => $permissionLabels[$permission] ?? ucfirst(str_replace('_', ' ', (string) $permission)),
    ];
}
$sessionUser = [
    'name' => (string) ($_SESSION['nombre'] ?? $_SESSION['full_name'] ?? $_SESSION['email'] ?? 'Usuario'),
    'email' => (string) ($_SESSION['email'] ?? $_SESSION['correo'] ?? ''),
    'role' => cengisalas_roles()['visitas'][$_SESSION['visitas_role'] ?? 'user'] ?? 'Consulta',
    'permissions' => $currentPermissions,
];
$jsonFlags = JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT;
?>
