<script>
const data = <?= json_encode($dashboardData, $jsonFlags) ?>;
const reviews = <?= json_encode($reviewRequests, $jsonFlags) ?>;
const internalContacts = <?= json_encode($internalContacts, $jsonFlags) ?>;
const requesterContacts = <?= json_encode($requesterContacts, $jsonFlags) ?>;
const sessionUser = <?= json_encode($sessionUser, $jsonFlags) ?>;
const csrf = <?= json_encode($visitsCsrf, $jsonFlags) ?>;
const canManageRooms = <?= $canManageReservaSalones ? 'true' : 'false' ?>;
const stateIcon={aprobado:'ti-check',rechazado:'ti-x',pendiente:'ti-clock',organizando:'ti-route',revision_director:'ti-user-check',notificada:'ti-bell',cancelada:'ti-ban'};
const stateLabel={aprobado:'Aprobado',rechazado:'Rechazado',pendiente:'Pendiente',organizando:'Organizando',revision_director:'En aprobación',notificada:'Visitante notificado',cancelada:'Cancelada'};
let activeRequest=null,replacementArea=null,availableRooms=[],activePaymentRow=null;
const byId=id=>document.getElementById(id);
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const showModal=id=>{const el=byId(id);if(el){el.classList.add('open');el.setAttribute('aria-hidden','false')}};
const hideModal=id=>{const el=byId(id);if(el){el.classList.remove('open');el.setAttribute('aria-hidden','true');if(id==='pdfModal'){byId('pdfViewer').removeAttribute('src');byId('pdfDownloadLink').setAttribute('href','#');if(activeDocumentUrl){URL.revokeObjectURL(activeDocumentUrl);activeDocumentUrl=''}}}};
function notify(message,error=false){const box=byId('visitActionMessage');box.textContent=message;box.className='visit-action-message show'+(error?' error':'');setTimeout(()=>box.classList.remove('show'),4200)}
let activeDocumentUrl='';
async function openDocumentPreview(button){
    const viewer=byId('pdfViewer');
    const endpoint=`ver_pdf.php?tipo=${encodeURIComponent(button.dataset.documentType)}&file=${encodeURIComponent(button.dataset.document)}`;
    const downloadLink=byId('pdfDownloadLink');
    showModal('pdfModal');
    // La URL directa se incluye también en el modal para que el navegador
    // pueda mostrar el PDF con la sesión actual, sin depender de blobs.
    downloadLink.href=endpoint;
    downloadLink.download=button.dataset.document||'';
    viewer.src=endpoint;

    try{
        const response=await fetch(endpoint,{credentials:'same-origin',cache:'no-store'});
        const contentType=(response.headers.get('content-type')||'').toLowerCase();
        const isLogin=response.redirected&&/\/login(?:\.html|\/)?(?:\?|$)/i.test(response.url);

        if(isLogin||contentType.includes('text/html')){
            window.location.assign(response.redirected?response.url:'../../../login/cengisalas_logout.php');
            return;
        }
        if(!response.ok)throw new Error(`No fue posible abrir el archivo (${response.status}).`);

        // Se mantiene la URL directa como fuente del visor. El fetch solo
        // valida que la sesión tenga acceso y evita que un error de lectura
        // del blob deje una ventana vacía.
        if (!contentType.includes('pdf') && !contentType.startsWith('image/')) {
            throw new Error('El documento no tiene un formato compatible.');
        }
    }catch(error){
        // Si la sesión sigue válida, dejamos el enlace directo disponible:
        // algunos navegadores bloquean fetch de PDFs grandes aunque el
        // endpoint sí pueda abrirse en una pestaña.
        if (/sesión|login|autoriz|acceso/i.test(error.message||'')) {
            hideModal('pdfModal');
            notify(error.message||'No fue posible abrir el documento.',true);
        } else {
            notify('La vista previa no pudo cargarse; usa “Abrir / descargar”.',true);
        }
    }
}

document.addEventListener('click',async event=>{
    const documentButton=event.target.closest('[data-document]');
    if(!documentButton)return;
    event.preventDefault();
    event.stopImmediatePropagation();
    await openDocumentPreview(documentButton);
},true);
function chip(label){return `<span class="chip">${escapeHtml(label)}</span>`}
function typeChip(type){const museum=['museo_azucar','museo'].includes(type),both=type==='ambos',label=both?'Cengicaña + Museo':(museum?'Museo del Azúcar':'Cengicaña'),icon=both?'ti-building-community':(museum?'ti-building-bank':'ti-building');return `<span class="type-chip ${both?'ambos':(museum?'museo':'cengicana')}"><i class="ti ${icon}" aria-hidden="true"></i>${label}</span>`}
function badge(state,reviewable,id){const body=`<i class="ti ${stateIcon[state]||'ti-clock'}" aria-hidden="true"></i>${stateLabel[state]||state}${reviewable?' · Revisar':''}`;return reviewable?`<button type="button" class="badge ${state}" data-review="${id}">${body}</button>`:`<span class="badge ${state}">${body}</span>`}
function paymentBadge(payment){const paid=payment==='pagado';return `<span class="badge ${paid?'pagado':'pendiente'}"><i class="ti ${paid?'ti-circle-check':'ti-clock'}" aria-hidden="true"></i>${paid?'Pagado':'Pendiente'}</span>`}
function progressDots(row){const state=row?.estado||'pendiente',steps={pendiente:1,organizando:2,revision_director:3,aprobado:4,notificada:5},terminal=['rechazado','cancelada'].includes(state),filled=terminal?(state==='rechazado'?3:2):(steps[state]||1),label=terminal?(state==='rechazado'?'Solicitud rechazada':'Solicitud cancelada'):`${stateLabel[state]||state}: ${filled} de 5 pasos`;return `<span class="progress-dots ${terminal?'terminal':''}" role="img" aria-label="${escapeHtml(label)}" title="${escapeHtml(label)}">${Array.from({length:5},(_,index)=>`<span class="progress-dot ${index<filled?'filled':''} ${index===filled-1?'current':''} ${terminal&&index===filled-1?'danger':''}"></span>`).join('')}</span>`}
function iconButton(icon,label,attrs='',cls=''){return `<button type="button" class="icon-btn ${cls}" aria-label="${escapeHtml(label)}" title="${escapeHtml(label)}" ${attrs}><i class="ti ${icon}" aria-hidden="true"></i></button>`}
const findRow=id=>data.find(row=>row.id===Number(id));
const visitTypeLabel=type=>({cengicana:'Visita a Cengicaña',museo_azucar:'Visita al Museo del Azúcar',museo:'Visita al Museo del Azúcar',ambos:'Cengicaña y Museo'})[type]||'Visita a Cengicaña';
function closeActionsMenu(){const root=byId('actionsMenuRoot');root.innerHTML='';root.setAttribute('aria-hidden','true');document.querySelectorAll('.actions-trigger[aria-expanded="true"]').forEach(button=>button.setAttribute('aria-expanded','false'))}
function actionMenuItem(icon,label,attributes='',options={}){const disabled=options.disabled?'disabled':'',title=options.title?` title="${escapeHtml(options.title)}"`:'',tone=options.tone||'neutral',lock=options.lock&&options.disabled?'<i class="ti ti-lock mi-lock" aria-hidden="true"></i>':'';return `<button type="button" ${attributes} ${disabled}${title}><span class="mi-dot ${tone}"><i class="ti ${icon}" aria-hidden="true"></i></span><span>${escapeHtml(label)}</span>${lock}</button>`}
function actionsMenuHTML(row){
  const inactive=['rechazado','cancelada'].includes(row.estado),paidVisit=Number(row.total)>0;
  let html='<div class="actions-menu" role="menu">';
  html+=actionMenuItem('ti-file-type-pdf','Ver carta',row.carta?`data-document="${escapeHtml(row.carta)}" data-document-type="cartas"`:'',{disabled:!row.carta,title:!row.carta?'La carta no está disponible.':'',tone:'neutral'});
  html+=actionMenuItem('ti-users','Ver listado de visitantes',`data-visitor-list="${row.id}"`,{disabled:!row.visitantes,title:!row.visitantes?'No se han registrado nombres de visitantes.':'',tone:'neutral'});
  html+='<hr>';
  html+=actionMenuItem('ti-route','Gestionar visita',!inactive&&row.puedeRevisar?`data-review="${row.id}"`:'',{disabled:inactive||!row.puedeRevisar,title:!row.puedeRevisar?'Requiere permiso para gestionar solicitudes.':(inactive?'La solicitud ya no está activa.':''),tone:'accent',lock:!row.puedeRevisar});
  html+=actionMenuItem('ti-school','Gestionar sala',!inactive&&row.puedeSala?`data-room-request="${row.id}"`:'',{disabled:inactive||!row.puedeSala,title:!row.puedeSala?'Requiere permiso para gestionar salones.':(inactive?'La solicitud ya no está activa.':''),tone:'amarillo',lock:!row.puedeSala});
  if(row.estado==='revision_director'){html+='<hr>';html+=actionMenuItem('ti-circle-check','Aprobar (Director)',`data-director-decision="approve" data-request-id="${row.id}"`,{tone:'success'});html+=actionMenuItem('ti-x','Rechazar (Director)',`data-director-decision="reject" data-request-id="${row.id}"`,{tone:'naranja'});}
  html+='<hr>';
  if(paidVisit){const paymentReady=['aprobado','notificada'].includes(row.estado);html+=actionMenuItem('ti-cash','Gestionar pago',(row.puedePago&&paymentReady)?`data-payment-request="${row.id}"`:'',{disabled:!row.puedePago||!paymentReady,title:!row.puedePago?'Requiere permiso de Administración.':(!paymentReady?'Disponible cuando la visita esté aprobada.':''),tone:'naranja',lock:!row.puedePago});}
  html+=actionMenuItem('ti-history','Ver seguimiento',`data-request-tracking="${row.id}"`,{tone:'accent'});
  if(row.puedeCorreo)html+=row.correoEnviado?actionMenuItem('ti-check','Correo enviado','',{disabled:true,tone:'success'}):actionMenuItem('ti-send','Enviar correo',`data-send-mail="${row.id}"`,{tone:'success'});
  if(row.puedeOcultar){html+='<hr>';html+=actionMenuItem('ti-eye-off','Ocultar solicitud',`data-hide-request="${row.id}"`,{tone:'naranja'});}
  html+='</div>';return html;
}
function openActionsMenu(button,id){const row=findRow(id);if(!row)return;const root=byId('actionsMenuRoot'),wasOpen=button.getAttribute('aria-expanded')==='true';closeActionsMenu();if(wasOpen)return;root.innerHTML=actionsMenuHTML(row);root.setAttribute('aria-hidden','false');button.setAttribute('aria-expanded','true');const menu=root.firstElementChild,rect=button.getBoundingClientRect();let left=Math.min(rect.right-menu.offsetWidth,window.innerWidth-menu.offsetWidth-8);left=Math.max(8,left);let top=rect.bottom+6;if(top+menu.offsetHeight>window.innerHeight-8)top=Math.max(8,rect.top-menu.offsetHeight-6);menu.style.left=`${left}px`;menu.style.top=`${top}px`}
function openRequestDetails(id){const row=findRow(id);if(!row)return;byId('requestDetailsTitle').textContent=`Detalle de solicitud #${row.id}`;const room=row.sala?`${row.sala.nombre} · ${row.sala.distribucion} · hasta ${row.sala.horaFin} (${row.sala.codigo})`:'Sin solicitud de salón';const visitorNames=row.visitantes?escapeHtml(row.visitantes):'<span class="secondary">Sin nombres registrados</span>';byId('requestDetailsBody').innerHTML=`<div class="detail-item"><small>Tipo de visita</small><strong>${escapeHtml(visitTypeLabel(row.tipo))}</strong></div><div class="detail-item"><small>Estado</small><strong>${escapeHtml(stateLabel[row.estado]||row.estado)}</strong></div><div class="detail-item"><small>Solicitante</small><strong>${escapeHtml(row.nombre)}</strong></div><div class="detail-item"><small>Institución</small><strong>${escapeHtml(row.inst)}</strong></div><div class="detail-item"><small>Correo</small><strong>${escapeHtml(row.correo)}</strong></div><div class="detail-item"><small>Teléfono</small><strong>${escapeHtml(row.tel||'No indicado')}</strong></div><div class="detail-item"><small>Fecha y hora</small><strong>${escapeHtml(row.fecha)} · ${escapeHtml(row.hora)}</strong></div><div class="detail-item"><small>Visitantes</small><strong>${row.vis}</strong></div><div class="detail-item wide"><small>Nombres de visitantes</small><strong class="detail-chip-list">${visitorNames}</strong></div><div class="detail-item wide"><small>Áreas</small><strong>${escapeHtml(row.areas.join(', ')||'Sin áreas asignadas')}</strong></div><div class="detail-item wide"><small>Salón</small><strong>${escapeHtml(room)}</strong></div>${Number(row.total)>0?`<div class="detail-item"><small>Costo</small><strong>Q${row.total.toFixed(2)}</strong></div><div class="detail-item"><small>Pago</small><strong>${row.pago==='pagado'?'Pagado':'Pendiente'}</strong></div>`:''}`;showModal('requestDetailsModal')}
function visitorNamesForRow(row){const source=Array.isArray(row.visitantesLista)&&row.visitantesLista.length?row.visitantesLista:(row.visitantes||'').split(', ');return source.map(name=>String(name||'').trim()).filter(Boolean)}
function visitorRowsHtml(row){const names=visitorNamesForRow(row);return names.length?names.map((name,index)=>`<tr><td>${index+1}</td><td>${escapeHtml(name)}</td></tr>`).join(''):'<tr><td colspan="2" class="visitor-empty">No se han registrado nombres de visitantes.</td></tr>'}
