function paymentDetailsHtml(row){const receipt=row.comprobante?`<div class="payment-receipt-row"><div><strong>Comprobante cargado</strong><small>${escapeHtml(row.comprobanteNombre||row.comprobante)}</small>${row.comprobanteFecha?`<small>${escapeHtml(row.comprobanteFecha)}</small>`:''}</div><a href="ver_comprobante_pago.php?id_solicitud=${row.id}" target="_blank" rel="noopener"><i class="ti ti-eye" aria-hidden="true"></i> Ver comprobante</a></div>`:'<div class="payment-receipt-row"><div><strong>Sin comprobante</strong><small>El solicitante todavía no ha enviado el archivo.</small></div></div>';return `<p class="visit-modal-description">Completa o comparte el formulario de pago de esta visita.</p><div class="payment-summary"><div><small>Estado del pago</small><div>${paymentBadge(row.pago)}</div></div><strong>Q${row.total.toFixed(2)}</strong></div><div class="payment-data-grid"><div class="payment-data-item"><small>Solicitante</small><strong>${escapeHtml(row.nombre)}</strong></div><div class="payment-data-item"><small>Institución</small><strong>${escapeHtml(row.inst)}</strong></div><div class="payment-data-item"><small>Fecha y hora</small><strong>${escapeHtml(row.fecha)} · ${escapeHtml(row.hora)}</strong></div><div class="payment-data-item"><small>Visitantes</small><strong>${row.vis}</strong></div><div class="payment-data-item wide"><small>Áreas</small><strong>${escapeHtml(row.areas.join(', ')||'Visita a CENGICAÑA')}</strong></div></div><div class="payment-link-row"><input id="paymentLinkInput" type="text" readonly placeholder="Generando enlace…"><button type="button" id="copyPaymentLinkInline" class="icon-btn" title="Copiar enlace" aria-label="Copiar enlace"><i class="ti ti-copy" aria-hidden="true"></i></button></div>${receipt}`}
