const monthKey=date=>date.slice(0,7);function monthLabel(key){const [year,month]=key.split('-');return ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][Number(month)-1]+' '+year}
function populateMonths(){const reportable=data.filter(r=>r.fecha&&!['cancelada','rechazado'].includes(r.estado)),source=reportable.length?reportable:data.filter(r=>r.fecha),months=[...new Set(source.map(r=>monthKey(r.fecha)))].sort().reverse(),select=byId('monthSelect');select.innerHTML=months.length?months.map(m=>`<option value="${m}">${monthLabel(m).replace(/^./,c=>c.toUpperCase())}</option>`).join(''):'<option value="">Sin datos</option>'}
