  byId('visitPhotosInput').disabled=inactive;
  byId('visitPhotoFiles').innerHTML=activeRequest.photos.length?activeRequest.photos.map(photo=>`<div class="visit-file-chip"><i class="ti ti-photo" aria-hidden="true"></i><a target="_blank" href="ver_archivo_gestion.php?request_id=${activeRequest.id}&kind=photo&id=${photo.id}">${escapeHtml(photo.name)}</a><button type="button" data-delete-photo="${photo.id}" title="Quitar fotografía"><i class="ti ti-x" aria-hidden="true"></i></button></div>`).join(''):'<span class="secondary">Aún no se han subido fotos.</span>';
  byId('visitContactSave').innerHTML=activeRequest.contactSaved?`<div><strong class="visit-inline-success"><i class="ti ti-circle-check" aria-hidden="true"></i> Ya está en la base de datos</strong><small>${escapeHtml(activeRequest.requester)} · ${escapeHtml(activeRequest.institution)} · ${escapeHtml(activeRequest.email)} · ${escapeHtml(activeRequest.phone)}</small></div>`:`<div><strong>${escapeHtml(activeRequest.requester)}</strong><small>${escapeHtml(activeRequest.institution)} · ${escapeHtml(activeRequest.email)} · ${escapeHtml(activeRequest.phone)}</small></div><button type="button" class="visit-button primary" data-save-contact><i class="ti ti-database-plus" aria-hidden="true"></i>Agregar a base de datos</button>`;
}
function defaultEnd(start){const [h,m]=start.split(':').map(Number);return `${String(Math.min(h+1,23)).padStart(2,'0')}:${String(m).padStart(2,'0')}`}
function renderConfigurations(){const space=availableRooms.find(item=>item.id===Number(byId('visitRoomSpace').value)),select=byId('visitRoomConfiguration');select.innerHTML=space?space.configurations.map(item=>`<option value="${item.id}">${escapeHtml(item.name)} · capacidad ${item.capacity}</option>`).join(''):'<option value="">Selecciona un salón</option>';select.disabled=!space;byId('submitVisitRoom').disabled=!space}
async function loadAvailability(){const end=byId('visitRoomEnd').value,message=byId('visitRoomAvailabilityMessage'),space=byId('visitRoomSpace');message.className='availability-message loading';message.textContent='Consultando salones disponibles en CengiSalas…';space.disabled=true;byId('submitVisitRoom').disabled=true;try{const response=await fetch(`cengisalas_salon_visita.php?request_id=${activeRequest.id}&end_time=${encodeURIComponent(end)}`),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible consultar disponibilidad.');availableRooms=body.spaces||[];space.innerHTML=availableRooms.length?'<option value="">Seleccionar salón</option>'+availableRooms.map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join(''):'<option value="">No hay salones disponibles</option>';space.disabled=!availableRooms.length;message.className='availability-message '+(availableRooms.length?'success':'warning');message.textContent=availableRooms.length?`${availableRooms.length} ${availableRooms.length===1?'salón disponible':'salones disponibles'} para este horario.`:'No hay salones con capacidad suficiente disponibles en ese horario.';renderConfigurations()}catch(error){availableRooms=[];space.innerHTML='<option value="">Sin disponibilidad</option>';message.className='availability-message error';message.textContent=error.message}}
function renderContacts(){const query=byId('contactSearchInput').value.trim().toLowerCase(),rows=internalContacts.filter(item=>!query||`${item.name} ${item.email} ${item.area}`.toLowerCase().includes(query));byId('contactResultCount').textContent=`${rows.length} ${rows.length===1?'contacto encontrado':'contactos encontrados'}`;byId('contactBody').innerHTML=rows.length?rows.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong></td><td>${escapeHtml(item.email)}</td><td><span class="contact-badge">${escapeHtml(item.role)}</span></td><td>${escapeHtml(item.area)}</td><td style="text-align:center"><a class="icon-btn" href="mailto:${encodeURIComponent(item.email)}" title="Escribir correo" aria-label="Escribir correo"><i class="ti ti-mail" aria-hidden="true"></i></a></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty-state"><i class="ti ti-address-book-off" aria-hidden="true"></i>No hay contactos configurados con esos criterios.</div></td></tr>'}
function filteredContactDatabase(){const query=byId('databaseSearchInput').value.trim().toLowerCase();return requesterContacts.filter(item=>!query||`${item.name} ${item.institution} ${item.email} ${item.phone}`.toLowerCase().includes(query))}
function displayDate(value){if(!value)return 'Sin fecha';const date=new Date(String(value).replace(' ','T'));return Number.isNaN(date.getTime())?String(value).slice(0,10):new Intl.DateTimeFormat('es-GT',{dateStyle:'medium'}).format(date)}
function renderContactDatabase(){const rows=filteredContactDatabase();byId('databaseResultCount').textContent=`${rows.length} ${rows.length===1?'contacto encontrado':'contactos encontrados'}`;byId('databaseBody').innerHTML=rows.length?rows.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong></td><td>${escapeHtml(item.institution)}</td><td>${escapeHtml(item.email)}</td><td>${escapeHtml(item.phone||'Sin teléfono')}</td><td>${item.requests}</td><td>${escapeHtml(displayDate(item.lastRequest))}</td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state"><i class="ti ti-database-off" aria-hidden="true"></i>No se encontraron solicitantes.</div></td></tr>'}
function contactsPayload(){return {generated_at:new Date().toISOString(),source:'Visitas - Solicitudes',total:requesterContacts.length,contacts:requesterContacts.map(item=>({name:item.name,institution:item.institution,email:item.email,phone:item.phone,request_count:item.requests,last_request:item.lastRequest}))}}
function openPayload(){byId('payloadBody').textContent=JSON.stringify(contactsPayload(),null,2);showModal('payloadModal')}
function downloadJson(){const blob=new Blob([JSON.stringify(contactsPayload(),null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='contactos_visitas.json';document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url)}
function downloadContactDatabase(){const rows=filteredContactDatabase();downloadCSV('contactos_solicitantes_visitas.csv',[['Nombre','Institución','Correo','Teléfono','Solicitudes','Última solicitud'],...rows.map(item=>[item.name,item.institution,item.email,item.phone,item.requests,item.lastRequest])])}
function renderRoles(){const initial=(sessionUser.name||sessionUser.email||'U').trim().charAt(0).toUpperCase();byId('sessionInitial').textContent=initial||'U';byId('sessionName').textContent=sessionUser.name||'Usuario';byId('sessionEmail').textContent=sessionUser.email||'Sesión autenticada de CengiSalas';byId('sessionRole').textContent=sessionUser.role;byId('permissionsGrid').innerHTML=sessionUser.permissions.length?sessionUser.permissions.map(permission=>`<div class="permission-card"><i class="ti ti-circle-check" aria-hidden="true"></i><div><strong>${escapeHtml(permission.name)}</strong><div class="secondary">${escapeHtml(permission.code)}</div></div></div>`).join(''):'<div class="empty-state">No hay permisos activos para esta sesión.</div>'}
byId('navSolicitudes').addEventListener('click',()=>switchTab('solicitudes'));byId('navReportes').addEventListener('click',()=>switchTab('reportes'));byId('navContactos').addEventListener('click',()=>switchTab('contactos'));byId('navAreas')?.addEventListener('click',()=>switchTab('areas'));byId('openAreasFromContacts')?.addEventListener('click',()=>switchTab('areas'));byId('navBaseDatos').addEventListener('click',()=>switchTab('basedatos'));byId('navRoles').addEventListener('click',()=>switchTab('roles'));byId('searchInput').addEventListener('input',renderTable);byId('statusFilter').addEventListener('change',renderTable);byId('typeFilter').addEventListener('change',renderTable);byId('monthSelect').addEventListener('change',renderReports);byId('reportTypeFilter').addEventListener('change',renderReports);byId('contactSearchInput').addEventListener('input',renderContacts);byId('databaseSearchInput').addEventListener('input',renderContactDatabase);byId('previewPayload').addEventListener('click',openPayload);byId('downloadPayload').addEventListener('click',downloadJson);byId('downloadContacts').addEventListener('click',downloadContactDatabase);byId('downloadSolicitudes').addEventListener('click',downloadRequests);byId('downloadReport').addEventListener('click',downloadReport);
document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){hideModal(close.dataset.close);return}const review=event.target.closest('[data-review]');if(review){activeRequest=reviews[String(review.dataset.review)];if(activeRequest&&!['rechazado','cancelado','cancelada'].includes(activeRequest.status)){try{if(['pendiente','enviado'].includes(activeRequest.status)){await postAction({action:'start_organizing',request_id:activeRequest.id});activeRequest.status='organizando';const row=findRow(activeRequest.id);if(row)row.estado='organizando';renderTable()}renderReview();showModal('visitReviewModal')}catch(error){notify(error.message,true)}}return}const doc=event.target.closest('[data-document]');if(doc){byId('pdfViewer').src=`ver_pdf.php?tipo=${encodeURIComponent(doc.dataset.documentType)}&file=${encodeURIComponent(doc.dataset.document)}`;showModal('pdfModal');return}const mail=event.target.closest('[data-send-mail]');if(mail){setBusy(mail,true);try{const form=new FormData();form.append('id_solicitud',mail.dataset.sendMail);const response=await fetch('enviar_correo.php',{method:'POST',body:form}),body=await response.json();if(!response.ok||!body.success)throw new Error(body.error||'No se pudo enviar.');notify('Correo enviado correctamente.');location.reload()}catch(error){notify(error.message,true);setBusy(mail,false)}return}const hide=event.target.closest('[data-hide-request]');if(hide){if(!confirm('¿Ocultar esta solicitud del dashboard?'))return;const form=document.createElement('form');form.method='POST';form.action='modulos/eliminar_solicitud.php';form.innerHTML=`<input type="hidden" name="id_solicitud" value="${hide.dataset.hideRequest}"><input type="hidden" name="from_unified" value="1">`;document.body.appendChild(form);form.submit();return}const replace=event.target.closest('[data-replace-area]');if(replace){replacementArea=activeRequest.areas.find(area=>area.originalId===Number(replace.dataset.replaceArea));byId('replaceAreaCurrent').textContent=replacementArea?.name||'';byId('replaceAreaSelect').value='';showModal('replaceAreaModal');return}const remove=event.target.closest('[data-remove-area]');if(remove){const area=activeRequest.areas.find(item=>item.originalId===Number(remove.dataset.removeArea));if(!confirm(`¿Quitar el área “${area?.name||''}” de esta solicitud?`))return;setBusy(remove,true);try{await postAction({action:'remove_area',request_id:activeRequest.id,original_area_id:Number(remove.dataset.removeArea)});location.reload()}catch(error){notify(error.message,true);setBusy(remove,false)}return}const decision=event.target.closest('[data-decision]');if(decision){if(!confirm('¿Confirmas que deseas cancelar esta solicitud?'))return;setBusy(decision,true);try{await postAction({action:'change_status',request_id:activeRequest.id,decision:'cancel'});location.reload()}catch(error){notify(error.message,true);setBusy(decision,false)}}});
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-action-menu]');if(trigger){event.preventDefault();event.stopPropagation();openActionsMenu(trigger,trigger.dataset.actionMenu);return}const menuButton=event.target.closest('.actions-menu button');const visitorList=event.target.closest('[data-visitor-list]');if(visitorList){closeActionsMenu();openVisitorList(visitorList.dataset.visitorList);return}const details=event.target.closest('[data-request-details]');if(details){closeActionsMenu();openRequestDetails(details.dataset.requestDetails);return}const tracking=event.target.closest('[data-request-tracking]');if(tracking){closeActionsMenu();openRequestTracking(tracking.dataset.requestTracking);return}const payment=event.target.closest('[data-payment-request]');if(payment){closeActionsMenu();openPaymentModal(payment.dataset.paymentRequest);return}const room=event.target.closest('[data-room-request]');if(room){closeActionsMenu();activeRequest=reviews[String(room.dataset.roomRequest)];if(!activeRequest)return;if(activeRequest.roomRequest){notify(`Ya existe la solicitud de salón ${activeRequest.roomRequest.code}.`);return}byId('visitRoomDate').value=activeRequest.date;byId('visitRoomStart').value=activeRequest.startTime;byId('visitRoomEnd').value=defaultEnd(activeRequest.startTime);showModal('visitRoomModal');loadAvailability();return}if(menuButton||!event.target.closest('.actions-menu'))closeActionsMenu()});
document.addEventListener('scroll',closeActionsMenu,true);
document.querySelectorAll('.visit-modal').forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)hideModal(modal.id)}));
byId('addVisitArea')?.addEventListener('click',()=>{byId('addAreaSelect').value='';showModal('addAreaModal')});byId('acceptAreaReplacement')?.addEventListener('click',async event=>{const area=Number(byId('replaceAreaSelect').value);if(!area)return notify('Selecciona el área de reemplazo.',true);setBusy(event.currentTarget,true);try{await postAction({action:'replace_area',request_id:activeRequest.id,original_area_id:replacementArea.originalId,new_area_id:area});location.reload()}catch(error){notify(error.message,true);setBusy(event.currentTarget,false)}});byId('acceptAreaAddition')?.addEventListener('click',async event=>{const area=Number(byId('addAreaSelect').value);if(!area)return notify('Selecciona el área que deseas agregar.',true);setBusy(event.currentTarget,true);try{await postAction({action:'add_area',request_id:activeRequest.id,new_area_id:area});location.reload()}catch(error){notify(error.message,true);setBusy(event.currentTarget,false)}});
byId('openVisitRoom')?.addEventListener('click',()=>{byId('visitRoomDate').value=activeRequest.date;byId('visitRoomStart').value=activeRequest.startTime;byId('visitRoomEnd').value=defaultEnd(activeRequest.startTime);showModal('visitRoomModal');loadAvailability()});byId('visitRoomEnd')?.addEventListener('change',loadAvailability);byId('visitRoomSpace')?.addEventListener('change',renderConfigurations);byId('submitVisitRoom')?.addEventListener('click',async event=>{setBusy(event.currentTarget,true);try{const response=await fetch('cengisalas_salon_visita.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,request_id:activeRequest.id,end_time:byId('visitRoomEnd').value,space_id:Number(byId('visitRoomSpace').value),configuration_id:Number(byId('visitRoomConfiguration').value)})}),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible solicitar el salón.');notify(`Solicitud ${body.request_code} enviada a CengiSalas.`);setTimeout(()=>location.reload(),900)}catch(error){notify(error.message,true);setBusy(event.currentTarget,false)}});
byId('toggleRequestPayment')?.addEventListener('click',event=>updatePayment(event.currentTarget));
byId('copyPaymentLink')?.addEventListener('click',copyPaymentLink);
byId('paymentReceiptWrap')?.addEventListener('click',()=>byId('paymentReceiptInput')?.click());
byId('sendPaymentEmail')?.addEventListener('click',async event=>{if(!activePaymentRow)return;setBusy(event.currentTarget,true);try{await preparePaymentLink('send_email');paymentFeedback(`Formulario enviado a ${activePaymentRow.correo||'el correo registrado'}.`)}catch(error){paymentFeedback(error.message,true)}finally{setBusy(event.currentTarget,false)}});
byId('paymentReceiptInput')?.addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file||!activePaymentRow)return;const button=byId('paymentReceiptWrap');button.classList.add('is-busy');try{const form=new FormData();form.append('csrf',csrf);form.append('id_solicitud',String(activePaymentRow.id));form.append('comprobante',file);const response=await fetch('gestionar_comprobante_pago.php',{method:'POST',body:form}),body=await response.json().catch(()=>({}));if(!response.ok||!body.success)throw new Error(body.error||'No fue posible cargar el comprobante.');paymentFeedback('Comprobante cargado y pago marcado como pagado.');setTimeout(()=>location.reload(),900)}catch(error){paymentFeedback(error.message,true);event.target.value=''}finally{button.classList.remove('is-busy')}});
